 const tx=new CommerceTransaction();await tx.add('company',{operatingMode:'TEST'},'company');await tx.add('customer',{name:'Synthetic issue customer'},'issue-customer');await tx.add('customer',{name:'Foreign customer'},'other-customer');
 await tx.add('site',{name:'Permitted site',active:true,customerId:'issue-customer',managerIds:['issue-foreman']},'issue-site');await tx.add('site',{name:'Restricted site',active:true,customerId:'issue-customer'},'restricted-site');await tx.add('site',{name:'Foreign site',active:true,customerId:'other-customer'},'foreign-site');
 await tx.add('location',{siteId:'issue-site',active:true,name:'3. OG',code:'3OG',nodeType:'FLOOR',floorLabelDe:'3. OG',internalNote:'private'},'issue-location');await tx.add('location',{siteId:'restricted-site',active:true,name:'EG'},'restricted-location');
 await tx.add('user',{active:true,name:'Internal reviewer',roles:['INTERNAL_BAULEITER'],siteIds:['issue-site'],permissions:['task.review','task.create']},'issue-foreman');await tx.add('user',{active:true,name:'Worker',roles:['EMPLOYEE'],siteIds:['issue-site']},'issue-worker');
 await tx.add('customer_membership',{userId:issueClient.userId,customerId:'issue-customer',siteIds:['issue-site'],permissions:['VIEW'],active:true,expiresAt:'2026-11-01T00:00:00.000Z'},'issue-membership');
 await tx.add('order',{siteId:'issue-site',customerId:'issue-customer',status:'CLOSED',pricingModel:'FIXED',baseNetCents:120000,approvedChangesNetCents:0,finalNetCents:120000},'issue-order');
 await tx.add('task',{siteId:'issue-site',locationId:'issue-location',orderId:'issue-order',title:'Fenster reinigen',state:'ACCEPTED',clientVisible:true,plannedQuantityMilli:100000,acceptedQuantityMilli:100000,reportedQuantityMilli:100000,unit:'M2',assigneeIds:['issue-worker'],checklist:[],dependencyIds:[],reviewCycle:1,completionKind:'ORIGINAL',billingScope:'CONTRACT',createdBy:'issue-foreman',notesInternal:'private staffing'},'issue-task');
 await tx.add('report_version',{reportId:'issued-report',siteId:'issue-site',customerId:'issue-customer',immutable:true,publishedAt:'2026-10-04T18:00:00.000Z',sha256:'immutable-sha',snapshot:{taskRows:[{taskId:'issue-task'}],totalNetCents:120000}},'issue-report-version');
 await tx.add('media_asset',{siteId:'issue-site',taskId:'issue-task',mimeType:'image/jpeg',visibility:'CLIENT_AFTER_APPROVAL',state:'APPROVED_FOR_CLIENT',clientBlobKey:'client-copy',uploadedBy:'issue-worker'},'issue-photo');
