async function combinedCommand(c:CommandContext,name:string,input:Data){const def=registry[name]!;if(!def||!c.actor.permissions.includes(def.permission))throw new DomainError('ACCESS_DENIED');return def.handler(c,def.schema.parse(input));}
describe('commerce to operations actual command roundtrips',()=>{
 it('dispatch resolves HR employee to user and the resulting canonical task can start, worklog, submit and pass separate quality review',async()=>{
  const s=await accept(),dc=context(s.tx,{...owner,permissions:['dispatch.manage','site.create','task.review']}),site=await combinedCommand(dc,'site.create',{code:'KNB-RT',name:'Roundtrip site',address:'Synthetic site address',customerId:s.order.data.customerId});
  await s.tx.add('employee',{userId:'roundtrip-user',active:true,skills:[],absences:[]},'hr-employee');await s.tx.add('user',{active:true,siteIds:[],roles:['EMPLOYEE']},'roundtrip-user');
  const reservation=await combinedCommand(dc,'dispatch.reserve',{orderId:s.order.id,employeeIds:['hr-employee'],startAt:'2026-10-06T08:00:00.000Z',endAt:'2026-10-06T10:00:00.000Z'});const assigned=await combinedCommand(dc,'dispatch.assign',{orderId:s.order.id,reservationId:reservation.id,siteId:site.id});const user=await s.tx.get('user','roundtrip-user');
  const wc=context(s.tx,{...worker,userId:user.id,siteIds:user.data.siteIds,permissions:['task.work','dispatch.acknowledge']}),task=(await s.tx.list('task')).find((t:Entity)=>t.data.orderId===s.order.id&&t.data.unit==='HOUR')!;
  await combinedCommand(wc,'crew_assignment.acknowledge',{id:assigned.assignment.id,employeeId:'hr-employee'});expect((await s.tx.get('order',s.order.id)).data.status).toBe('SCHEDULED');
  await combinedCommand(wc,'task.start',{taskId:task.id});const log=await combinedCommand(wc,'task.worklog',{taskId:task.id,quantityMilli:6000,description:'Actual synthetic task result'});expect(log.data).toMatchObject({authorId:user.id,employeeIds:[user.id],unit:'HOUR',quantityMilli:6000});
  await combinedCommand(wc,'task.submit',{taskId:task.id});await expect(combinedCommand({...wc,actor:{...wc.actor,permissions:['task.review']}},'task.review',{taskId:task.id,decision:'ACCEPT'})).rejects.toMatchObject({code:'ACCESS_DENIED'});const reviewed=await combinedCommand(dc,'task.review',{taskId:task.id,decision:'ACCEPT'});
  expect(reviewed.data).toMatchObject({state:'ACCEPTED',acceptedQuantityMilli:6000,sourceQuoteId:s.quote.id,sourceQuoteVersion:1,priority:'NORMAL',clientVisible:false,billingScope:'CONTRACT'});expect((await s.tx.list('task_review'))[0]!.data.worklogIds).toEqual([log.id]);expect(await s.tx.list('task')).toHaveLength(3);expect((await s.tx.get('order',s.order.id)).data.finalNetCents).toBe(24000);
 });
 it('accepted Nachtrag is the canonical operations approval for additional scope while internal approval alone is insufficient',async()=>{
  const s=await accept(true),site=await combinedCommand(context(s.tx,{...owner,permissions:['site.create']}),'site.create',{code:'KNB-CO',name:'Nachtrag site',address:'Synthetic address',customerId:s.order.data.customerId});const order=await s.tx.get('order',s.order.id);await s.tx.save(order,{...order.data,siteId:site.id});
  let change=await run(s.c,'change_order.create',{orderId:s.order.id,reason:'Additional agreed service',scopeAdded:['Extra work'],deltaNetCents:12000,expiresAt:'2026-11-01T00:00:00.000Z',scheduleImpact:'No time promise',legalTemplateId:'synthetic-template'});change=await run(s.c,'change_order.approve',{id:change.id,reviewReason:'Separate internal quote review'});expect(change.data).toMatchObject({state:'APPROVED_FOR_CUSTOMER',status:'APPROVED_FOR_CUSTOMER',siteId:site.id});
  const tc=context(s.tx,{...owner,permissions:['task.create']}),input={siteId:site.id,orderId:s.order.id,title:'Accepted additional scope',completionKind:'ADDITIONAL_SCOPE',billingScope:'CHANGE_ORDER',changeOrderId:change.id};await expect(combinedCommand(tc,'task.create',input)).rejects.toMatchObject({code:'NEEDS_APPROVAL'});
  change=await run(s.cc,'change_order.accept',{id:change.id});expect(change.data).toMatchObject({state:'ACCEPTED',status:'ACCEPTED'});const task=await combinedCommand(tc,'task.create',input);expect(task.data).toMatchObject({completionKind:'ADDITIONAL_SCOPE',billingScope:'CHANGE_ORDER',changeOrderId:change.id,orderId:s.order.id,siteId:site.id});expect((await s.tx.get('order',s.order.id)).data.finalNetCents).toBe(132000);
 });
 it('portal projects actual operations site codes and archived status without exposing internal site fields',async()=>{
  const s=await accept(),sc=context(s.tx,{...owner,permissions:['site.create']}),site=await combinedCommand(sc,'site.create',{code:'KNB-PORTAL',name:'Customer place',address:'Synthetic address',customerId:s.order.data.customerId});const portal=await run(s.cc,'customer.portal',{customerId:s.order.data.customerId});expect(portal.sites).toEqual([expect.objectContaining({id:site.id,businessCode:'KNB-PORTAL',status:'ACTIVE',active:true})]);
  await s.tx.save(site,{...site.data,active:false,privateNote:'Do not project'});const archived=await run(s.cc,'customer.portal',{customerId:s.order.data.customerId});expect(archived.sites[0]).toMatchObject({businessCode:'KNB-PORTAL',status:'ARCHIVED',active:false});expect(JSON.stringify(archived)).not.toContain('Do not project');
 });
});
